"""Execute the actual Android routing adapter with real sequence and persistence classes."""
from pathlib import Path
import subprocess,tempfile
files={
'io/tvos/RemoteShortcuts.java':Path('app/src/io/tvos/RemoteShortcuts.java').read_text(),
'io/tvos/remote/TapSequence.java':Path('app/src/io/tvos/remote/TapSequence.java').read_text(),
'io/tvos/remote/RemoteBindings.java':Path('app/src/io/tvos/remote/RemoteBindings.java').read_text(),
'io/tvos/RemoteVolume.java':'package io.tvos;class RemoteVolume {static final String PERMISSION="private";}',
'io/tvos/RemoteShortcutActions.java':'package io.tvos;import java.util.*;class RemoteShortcutActions {static final List<String> log=new ArrayList<>();static void run(android.content.Context c,String a){log.add(a);}}',
'android/content/Intent.java':'package android.content;public class Intent {public static final String ACTION_SCREEN_OFF="off";}',
'android/content/IntentFilter.java':'package android.content;public class IntentFilter {public IntentFilter(String s){}public void addAction(String s){}}',
'android/content/BroadcastReceiver.java':'package android.content;public abstract class BroadcastReceiver {public abstract void onReceive(Context c,Intent i);}',
'android/content/Context.java':'''package android.content;public class Context {public static final int RECEIVER_NOT_EXPORTED=4;public final java.io.File dir;public int registered,unregistered,flags;public BroadcastReceiver receiver;public Context(java.io.File f){dir=f;}public java.io.File getFilesDir(){return dir;}public Intent registerReceiver(BroadcastReceiver r,IntentFilter f,String p,Object h){receiver=r;registered++;return null;}public Intent registerReceiver(BroadcastReceiver r,IntentFilter f,String p,Object h,int mode){flags=mode;return registerReceiver(r,f,p,h);}public void unregisterReceiver(BroadcastReceiver r){unregistered++;}}''',
'android/os/Build.java':'package android.os;public class Build {public static class VERSION {public static int SDK_INT=33;}}',
'android/os/Looper.java':'package android.os;public class Looper {public static Looper getMainLooper(){return new Looper();}}',
'android/os/SystemClock.java':'package android.os;public class SystemClock {public static long now;public static long uptimeMillis(){return now;}}',
'android/os/Handler.java':'''package android.os;import java.util.*;public class Handler {public Handler(Looper l){}static final Map<Runnable,Long> jobs=new HashMap<>();public boolean postDelayed(Runnable r,long d){jobs.put(r,SystemClock.now+d);return true;}public void removeCallbacks(Runnable r){jobs.remove(r);}public static void advance(long n){long end=SystemClock.now+n;while(true){Runnable next=null;long at=Long.MAX_VALUE;for(Map.Entry<Runnable,Long> e:jobs.entrySet())if(e.getValue()<at){next=e.getKey();at=e.getValue();}if(next==null||at>end)break;SystemClock.now=at;jobs.remove(next);next.run();}SystemClock.now=end;}}''',
'android/view/InputDevice.java':'package android.view;public class InputDevice {public static final int SOURCE_GAMEPAD=1025,SOURCE_JOYSTICK=16777232;public String name="RC";public String getName(){return name;}}',
'android/view/KeyEvent.java':'''package android.view;public class KeyEvent {public static final int ACTION_DOWN=0,ACTION_UP=1,FLAG_CANCELED=32;public int action,code,scan,device=1,source=257,flags,repeat;public InputDevice input=new InputDevice();public KeyEvent(int a,int c,int s){action=a;code=c;scan=s;}public KeyEvent(KeyEvent e){action=e.action;code=e.code;scan=e.scan;device=e.device;source=e.source;flags=e.flags;repeat=e.repeat;input=e.input;}public int getKeyCode(){return code;}public int getScanCode(){return scan;}public int getDeviceId(){return device;}public int getSource(){return source;}public InputDevice getDevice(){return input;}public int getAction(){return action;}public int getRepeatCount(){return repeat;}public int getFlags(){return flags;}public long getDownTime(){return 0;}public boolean isCanceled(){return (flags&FLAG_CANCELED)!=0;}public static KeyEvent changeAction(KeyEvent e,int a){KeyEvent c=new KeyEvent(e);c.action=a;return c;}public static KeyEvent changeFlags(KeyEvent e,int f){KeyEvent c=new KeyEvent(e);c.flags=f;return c;}public static KeyEvent changeTimeRepeat(KeyEvent e,long t,int r){KeyEvent c=new KeyEvent(e);c.repeat=r;return c;}}''',
'io/tvos/ShortcutsTest.java':'''package io.tvos;import io.tvos.remote.*;import android.content.*;import android.view.*;import android.os.*;import java.nio.file.*;import java.util.*;
public class ShortcutsTest {static void check(boolean b,String s){if(!b)throw new AssertionError(s);}static KeyEvent key(int a,int c){return new KeyEvent(a,c,c==23?353:400);}static void tap(RemoteShortcuts r,int c){check(r.onKey(key(0,c)),"down consumed");check(r.onKey(key(1,c)),"up consumed");}
public static void main(String[] args)throws Exception {for(int sdk:new int[]{28,33}){Build.VERSION.SDK_INT=sdk;Path root=Files.createTempDirectory("remote-adapter");Context c=new Context(root.toFile());List<KeyEvent> original=new ArrayList<>();RemoteShortcutActions.log.clear();
RemoteBindings.Binding home=new RemoteBindings.Binding(23,353,"RC",false,new String[]{"default","settings","vpn"});RemoteBindings.Binding global=new RemoteBindings.Binding(183,400,"RC",true,new String[]{"play","next",""});RemoteBindings.write(c.dir,Arrays.asList(home,global));
RemoteShortcuts local=new RemoteShortcuts(c,false,original::add);try {tap(local,23);Handler.advance(300);check(original.size()==2&&original.get(0).action==0&&original.get(1).action==1,"original locally routed once");original.clear();for(int i=0;i<3;i++)tap(local,23);Handler.advance(500);check(original.isEmpty()&&RemoteShortcutActions.log.equals(Arrays.asList("vpn")),"triple suppresses native action");RemoteShortcutActions.log.clear();
tap(local,23);check(!local.onKey(key(0,20)),"navigation stays native");Handler.advance(1000);check(original.isEmpty(),"navigation cancels delayed click");tap(local,23);c.receiver.onReceive(c,new Intent());Handler.advance(1000);check(original.isEmpty(),"settings/screen update cancels pending click");
KeyEvent foreign=key(0,23);foreign.input.name="Other";check(!local.onKey(foreign),"device name isolated");KeyEvent gamepad=key(0,23);gamepad.source=InputDevice.SOURCE_GAMEPAD;check(!local.onKey(gamepad),"gamepad passthrough");
local.onKey(key(0,23));local.cancel();check(local.onKey(key(1,23)),"cancelled trailing release consumed");Handler.advance(1000);check(original.isEmpty(),"orphan release cannot launch");
local.onKey(key(0,23));Handler.advance(500);check(original.size()==1,"hold starts native down");local.cancel();check(original.size()==2&&original.get(1).isCanceled(),"native hold ends with cancellation");
}finally{local.close();local.close();}check(c.registered==1&&c.unregistered==1&&c.flags==(sdk>=33?4:0),"private receiver lifecycle");
Context g=new Context(root.toFile());RemoteShortcuts service=new RemoteShortcuts(g,true,null);try {check(service.homeBinding(key(0,23))&&!service.onKey(key(0,23)),"global adapter leaves Home-only key alone");tap(service,183);tap(service,183);check(RemoteShortcutActions.log.equals(Arrays.asList("next")),"global double action once");RemoteShortcutActions.log.clear();tap(service,183);KeyEvent otherDown=key(0,183);otherDown.device=2;service.onKey(otherDown);service.onKey(key(1,183));KeyEvent otherUp=key(1,183);otherUp.device=2;service.onKey(otherUp);Handler.advance(300);check(RemoteShortcutActions.log.equals(Arrays.asList("play")),"two identical remote names cannot combine taps across physical device IDs");RemoteShortcutActions.log.clear();RemoteBindings.write(g.dir,Collections.emptyList());service.reload();check(!service.onKey(key(0,183)),"removed mapping passes through");}finally{service.close();}
try(java.util.stream.Stream<Path> paths=Files.walk(root)){paths.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.delete(p);}catch(Exception e){throw new RuntimeException(e);}});}}
System.out.println("PASS: actual Android Home/global adapters SDK28/33, identity/gamepad exclusion, delayed/native/triple/hold behavior, navigation/reload cancellation, removal and private receiver cleanup");}}
'''}
with tempfile.TemporaryDirectory() as directory:
 root=Path(directory)
 for name,content in files.items():
  p=root/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)
 subprocess.run(['java','com.sun.tools.javac.Main','--release','8','-Xlint:all,-options','-Werror','-d',directory,*map(str,root.rglob('*.java'))],check=True)
 subprocess.run(['java','-cp',directory,'io.tvos.ShortcutsTest'],check=True)
